(function(root){
const C=root.IC_FPGA_CATALOG,D=root.IC_FPGA_CONTENT;
const q=(q,options,correct,why)=>({q,options,correct,why});
function add(id,title,main,bridge,data){C.modules.push({id,title,main,bridge,previous:null,group:'通用 RTL 工程'});D[id]={...data,source:'synthesis',completion:['我能解释本课硬件与边界条件','我已完成两份练习并预测关键波形','我区分了理解、自查和实际工具证据']};}
add('22','流水线：延迟与吞吐',8,'sequential',{
 goals:['用寄存器分割组合路径','让 valid 和数据在同一拍到达'],
 concepts:[['为什么需要流水线','组合路径越长，信号到下一个寄存器前稳定下来所需时间可能越长。把算术分到多个寄存器级能缩短每级组合逻辑，但每级多一次等待。流水线不是把整幅图放进一个时钟里瞬间算完，而是让不同像素同时占据不同处理级。是否真的能提高频率还要看实现后的时序报告。'],['延迟不等于吞吐','本课程按寄存器边界定义：输入在一个边沿被接受，经过 L 个寄存器级，在该输入对应的第 L 个采样边沿后可观察结果。测试台必须明确编号约定。对于每级都能接收、没有阻塞的四级流水线，填满后每拍可出一个像素，首个像素仍需经历四级；行缓存还会额外等待足够的行。'],['气泡也必须前进','valid=0 表示这一拍没有有效样本，不代表所有流水线停止。若仅在 valid=1 时移动 valid 寄存器，旧 valid 可能卡住造成重复输出。下面单级在每拍更新 valid，只在有效输入时写 data。无效拍 data 可以保持，但下游必须忽略它。发生 ready 背压时，整个协议需要额外的保持规则。']],
 hardware:'每个寄存器保存一份数据，对应一个有效位。图像窗口的 x/y、帧标志也属于数据标签，必须和像素经过相同延迟。',diagram:['像素 A / valid','寄存器级 1','寄存器级 2','输出 A / valid'],code:'rtl/pipeline_stage.v',
 steps:['画出输入样本 A、B、气泡、C 的四列时序表，先不写代码。','串联两个单级模块，测试台在下降沿给数据，在上升沿后检查结果。','输入 valid 序列 1、1、0、1，确认输出序列出现同样的气泡，并核对每个字节。','记录你采用的边沿编号和复位时清空 valid 的方式；再看综合与时序报告。'],expected:'两级输出保持 A、B、气泡、C 顺序；复位后旧样本不得以有效输出泄漏。',wave:{heads:['边沿','输入','级1 后','级2 后'],rows:[['E0','A','A','无效'],['E1','B','B','A'],['E2','气泡','无效','B'],['E3','C','C','无效'],['E4','气泡','无效','C']]},
 mistakes:['把四级理解成每四拍才处理一个样本。','有效位只在有输入时移动。','只延迟像素，忘了坐标或阈值。'],debug:['给每个样本加递增编号。','先找第一次 valid 不一致。','确认每级组合运算使用哪一拍数据。'],guided:{task:'写两级串联的接口与 A/B/气泡/C 时序，注明首个结果在哪个边沿可观察。',steps:['画寄存器边界。','逐拍移动样本标签。','对齐数据和 valid。'],hint:'E0 输入 A，级1 得到 A；E1 后级2 才得到 A。'},independent:{task:'独立实现三级“加1、乘2、饱和到255”流水线，输入间插入无效拍，写出溢出输入的预期结果。',hint:'中间值扩位，valid 每拍移动；不要过早截断。'},quiz:[q('四级满流水线可以每拍输出吗？',['在各级无阻塞时可以','一定四拍一个','一定零延迟'],0,'吞吐与首个样本延迟是不同指标。'),q('无效拍时 valid 应？',['停止更新','按协议把气泡推进','强制为1'],1,'下游靠有效位识别样本。')]});
add('23','同步 RAM 与 BRAM',8,'sequential',{
 goals:['理解按地址存储与同步读延迟','分清 RTL 数组和实际 BRAM 映射'],
 concepts:[['为什么不用一长串独立寄存器','宽 W 的灰度行包含 W×8 位。多行缓存的容量增长很快，专用存储块通常比散布的触发器更适合。RTL 中写 reg [7:0] mem[0:W-1] 只声明逻辑存储，不保证一定映射 BRAM；容量、端口、读写方式、复位和厂商模板都会影响综合结果。'],['同步读有一拍接口延迟','在有效边沿，RAM 接受 addr 并让 dout 在边沿后更新。使用同一 always 或同一边沿的下游寄存器读 dout 时，拿到的是旧值，所以坐标和当前行像素必须按这拍延迟配套。不能用 Python 数组立即返回的直觉理解同步 RAM。先画地址请求与数据响应两列，再决定窗口在哪一拍接收。'],['同地址读写与复位','示例非阻塞赋值表达读旧数据后写新数据的 RTL 行为，但不同器件的读写冲突模式需要核对，综合模板也可能改变映射。避免不经验证依赖冲突模式。不要在复位时循环清零长数组然后期待免费 BRAM；更常见的是复位地址/有效计数，等待前两行填满后才允许窗口有效。']],hardware:'RAM 的地址译码选择一个存储字，输出寄存器保存读值。行缓存需要两行历史，加上很短的窗口移位寄存器。',diagram:['地址 / 写入数据','同步存储阵列','读输出寄存器','延迟后的坐标 / valid'],code:'rtl/sync_ram.v',steps:['建立16字节小存储，先按地址写入 0..15。','读取同一序列，记录地址边沿与 dout 的对应关系。','专门测试同地址读写，标记预期模式，再从目标工具报告确认资源与实际模式。','扩大容量时检查是否推断存储块，不把工具推断结果当语法保证。'],expected:'能说明 dout 对应哪个地址采样边沿；未写地址或复位后尚未填充的数据不会被当有效像素。',mistakes:['数组一定等于 BRAM。','把旧 dout 配给当前 x/y。','整块缓存复位造成资源膨胀。'],debug:['先用地址值当数据。','检查读写冲突。','先验证有效计数，再观察未知存储值。'],guided:{task:'为连续请求地址0、1、2画同步读波形，标出下游触发器何时能采到地址1的值。',steps:['写请求拍。','写边沿后 RAM 输出。','再写下游采样。'],hint:'下游同边沿采旧 dout；不要把两次寄存器更新合成一次。'},independent:{task:'设计640像素、每像素8位的两行存储容量，列出使用 BRAM 前必须验证的三项接口行为。',hint:'仅行数据为2×640×8=10240位，窗口和控制另算。'},quiz:[q('同步读的下游同边沿看到？',['刚请求地址的新数据','边沿前的旧 dout','整个存储器'],1,'非阻塞更新在采样之后可见。'),q('RTL 数组是否保证 BRAM？',['保证','取决于模板与工具映射','永远不是'],1,'检查综合资源与器件支持。')]});
add('24','FIFO：有边界的排队',10,'counter',{
 goals:['定义满空和读写接受条件','区分单时钟 FIFO 与跨时钟 FIFO'],concepts:[['队列是接口承诺','FIFO 保证先写入的数据先读出。写指针、读指针和占用量都由时钟边沿更新。接口必须说明 push 在 full 时怎样处理，pop 在 empty 时是否无效；不能默默覆盖未读数据。本课选择保守策略：满时即使同拍读出也不接收新写入，便于初学者验证。'],['同时读写与存储延迟','非满非空时同拍读写使占用量不变，但两个指针各前进一步。示例使用寄存器输出，out_valid 标记刚刚成功读出的数据；不能因为队列非空就把 dout 当第一项实时值。空时的同拍 push/pop 只接受写入，不做自动旁路。深 FIFO 可尝试 BRAM，但接口延迟要保持一致。'],['单时钟不是异步 FIFO','本课所有端口在同一个 clk 下工作。摄像头与显示时钟不同不能直接把这个 FIFO 接过去，也不能给一个多位地址总线每位加两个寄存器就声称安全跨域。跨域 FIFO 需要专门的指针同步与满空判定，当前先认识边界，使用经过验证的厂商 IP 或团队方案。']],hardware:'读写指针是环形地址计数器，占用量需要表示0到容量，因此深度4要3位 count，而不是2位。',diagram:['写入接受条件','4字节队列','读出接受条件','已注册输出 / valid'],code:'rtl/fifo4.v',steps:['把 A/B/C/D 依次入队，确认 full 后第五次写被拒绝。','按顺序读四次，比较每次 out_valid 和字节；空读不产生有效结果。','测试同时读写、指针回绕和半满时复位。','把实际行为与接口规格逐条对照，记录吞吐限制。'],expected:'不丢失、不重复、不乱序，满写/空读策略符合文档；复位清空控制状态。',mistakes:['count 位宽只按地址宽度定义。','认为 !empty 就表示 dout 有新数据。'],debug:['记录接受事件而非请求次数。','用唯一递增数据检查顺序。','测试满空边界和回绕。'],guided:{task:'列出空/半满/满三种情况下同时 push/pop 的接受结果与 count 变化。',steps:['先求put。','再求take。','最后算新count。'],hint:'满时put=0、take=1，count减1；空时反过来。'},independent:{task:'为 fifo4 编写自检测试台，覆盖满写、空读、同时读写、回绕和复位。',hint:'软件队列只在put/take发生时更新，不要只统计push/pop。'},quiz:[q('深度4队列的占用量至少几位？',['2','3','4'],1,'需要表示0..4。'),q('本例能直接连接两个时钟域吗？',['能','不能','修改文件名即可'],1,'这是单时钟 FIFO。')]});
add('25','流接口与 valid / ready',8,'module',{
 goals:['精确定义一次数据传输','对齐 valid、像素和坐标'],concepts:[['valid-only 与 ready/valid 不同','基础图像工程先约定下游每拍都能接收，所以 pixel_valid=1 就接受一个像素；无效拍是空白或气泡，坐标不增加。加入 ready 后，只有 valid&&ready 的边沿才传输。协议中没有 ready 的上游不能被你悄悄暂停，系统必须保证带宽或加足够的缓存。'],['背压下数据必须保持','当 out_valid=1 且 out_ready=0，发送方需要保持数据与有效位，直到接收成功。下面单项弹性缓冲在空时允许输入，在旧输出本拍被消费时也可用新输入替换。它只有一个样本容量，不能解决无限长的下游停顿。'],['标签也是数据的一部分','图像样本不只有灰度值，还可能有 x/y、sof/eol。若数据被寄存两拍而坐标直接穿过，画面可能错位但仍看起来像边缘。测试时用唯一编号和不规则气泡，核对每个输出的标签；团队接口要明确谁负责计数、谁定义一帧开始。']],hardware:'一个数据寄存器和一个占用有效位形成一格缓冲；ready 是接收条件，不是额外的时钟。',diagram:['in_data / in_valid','一格寄存器 / valid','out_data / out_valid','out_ready 反馈'],code:'rtl/elastic_stage.v',steps:['先用时序表定义一次接受事件。','下游 ready 拉低三拍，观察数据和 valid 保持。','恢复 ready，同拍送下一字节，确认无重复或丢失。','为比赛基线写下“无背压”条件，接口改变时同步修改Golden输入与测试台。'],expected:'输出被阻塞时稳定；只统计被接受的样本；坐标与数据不分离。',mistakes:['把valid当时钟。','背压时数据仍变化。'],debug:['在传输边沿打印样本编号。','检查气泡是否误推进坐标。'],guided:{task:'解释 in_ready=!out_valid||out_ready 的两种允许接收情况。',steps:['空缓冲。','旧值被消费。','满且未消费。'],hint:'最后一种必须保持。'},independent:{task:'给接口加坐标字段，写下阻塞四拍再恢复的预测波形与断言。',hint:'坐标和像素一起保存，不能独立更新。'},quiz:[q('ready/valid 传输发生在？',['valid&&ready的采样边沿','任一信号为1','数据发生变化时'],0,'这是双方共同接受事件。'),q('基线valid-only无效拍坐标应？',['增加','保持','随机'],1,'坐标按有效像素计数。')]});
add('26','位宽、定点、截断与饱和',8,'width',{
 goals:['从范围推导位宽','分清舍入、截断、饱和'],concepts:[['先求范围再选类型','8位无符号表示0..255；两个8位数相加最大510，需要9位。signed的最高位是符号，11位二补码范围为-1024..1023。负梯度不能塞进unsigned后再期待 abs 修好。更重要的是表达式运算发生时就要足够宽，接到更宽输出并不能补回已经丢掉的高位。'],['定点的小数点是约定','Q8系数把真实系数乘256存成整数。例如384代表1.5，sample×gain 的乘积带8个小数位。右移8恢复整数；加128再右移是非负数的一种最近舍入，而不加就是向下截断。负数舍入规则另外定义，不能把同一常数公式无条件用于 signed 数据。'],['饱和防止亮像素变黑','若结果超过255直接取低8位，300会变成44，造成严重视觉反转。饱和先比较范围，大于255输出255，再处理合法低8位。灰度公式系数和为256，所以最大65280，16位乘加和够用；图像Sobel幅值却远超255，要在阈值判断后才变成二值像素。']],hardware:'扩位是增加运算通路的位数，截断是丢线，饱和是比较器加多路选择器；不同规则直接改变真实电路输出。',diagram:['8位样本 × Q8系数','宽乘积 + 舍入量','右移8','比较 / 饱和'],code:'rtl/fixed_scale.v',steps:['为最大输入求乘积与舍入后的上界。','检查 HDL 中每个中间信号的signed声明与宽度。','对0、1、最大值和饱和边界写自检。','用Python整数公式逐点比较，固定所有舍入规则。'],expected:'系数384时，sample=200输出255而不是44；sample=1的最近舍入结果为2。',mistakes:['先窄位左移再扩位。','把截断当饱和。','signed和unsigned隐式混合。'],debug:['打印十进制和位模式。','给每个中间节点列范围表。','从第一处算术偏差查起。'],guided:{task:'推导8位样本乘9位无符号系数需要的乘积宽度，再考虑加128需要的裕量。',steps:['最大255×511。','对照2的幂。','明确加法是否再扩1位。'],hint:'乘积用17位，示例加法扩为18位避免模糊的表达式宽度。'},independent:{task:'用Python逐个检查 sample=0..255、gain=384，与自己写的定点模块比较；记录截断版与舍入版差别。',hint:'规格一旦确定，RTL必须逐值一致；和浮点的误差是另外一项。'},quiz:[q('unsigned 8位加法最大510需？',['8位','9位','7位'],1,'2^9-1=511。'),q('300直接保留低8位得到？',['255','44','300'],1,'饱和需要额外比较，截断不会饱和。')]});
add('27','时钟域与复位边界意识',10,'clock',{
 goals:['认识单比特同步器的适用范围','为团队接口标明时钟与复位'],concepts:[['不同钟表不能假装同一拍','异步输入可能在寄存器采样窗口附近变化，产生亚稳风险。两级同步器能降低单比特电平传播不稳定状态的概率，却不是任意数据通信协议；窄脉冲可能漏采，多位总线每位同步也可能得到不同时间拼接的值。当前算法核先限定单时钟，跨域交给明确的边界模块。'],['复位也有时序关系','示例算法RTL采用低有效同步复位，只有clk有效边沿才清状态。板上按钮不应直接当作所有逻辑的同步复位输入而不作处理。若系统使用异步断言、同步释放方案，需要按各时钟域设计并验证；这是一项接口约定，不是名字 rst_n 自动赋予的行为。'],['现在学会识别风险即可','先列camera_clk、algorithm_clk、display_clk是否相同，谁提供缓存或跨域FIFO，复位什么时候可以释放。没有经过验证的跨域方案时把集成标为BLOCKED，并继续完成单域算法仿真。这样比赛仍向前推进，同时不把高级CDC变成当前初学路线的中心。']],hardware:'单比特控制同步只是输入边界的一小部分；按钮还需要消抖，视频数据流需要一致的多位传输方案。',diagram:['异步单比特电平','同步寄存器1','同步寄存器2','本时钟域逻辑'],code:'rtl/button_filter.v',steps:['在模块接口表中给每个信号写来源时钟。','找出不同域之间的数据和控制，区分电平、脉冲、多位流。','核对团队选择的CDC模块和复位策略，不自行删除时序约束。','保留当前算法核单域条件，仿真复位清空有效位与重新填窗。'],expected:'能指出同步器不能解决的两类问题，并给团队提出明确接口问题。',mistakes:['所有信号各加两个FF就安全。','异步输入等于按键抖动。'],debug:['先画域边界。','检查脉冲宽度与接受规则。','查复位后第一帧是否被完整重建。'],guided:{task:'分别判断按钮电平、一个源域时钟宽的脉冲、24位像素总线，能否只用两级同步器直接传递。',steps:['看是否多位一致。','看脉冲是否可能漏掉。','最后选待确认协议。'],hint:'仅稳定单比特电平适合直接讨论两级同步；其余需要协议。'},independent:{task:'为摄像头→算法→显示写一张时钟域与复位责任表，未知条件标待团队确认。',hint:'不把未知时钟当作相同频率或相同相位。'},quiz:[q('多位像素逐位两级同步能保证完整字吗？',['能','不能','只要文件名正确'],1,'各位可能在不同拍稳定。'),q('同步复位生效需要？',['时钟边沿','仅改变信号','打开IDE'],0,'示例在posedge采样复位。')]});
})(window);
